// Collect all successfully scraped pages from Merge Results
const items = $input.all();
const pages = items
  .filter(item => item.json.success === true && item.json.data?.markdown)
  .map(item => item.json.data.markdown);

// Strip cookie-consent widget noise (CookieYes, OneTrust, Cookiebot, etc.)
// These widgets render a large block listing every individual cookie name,
// duration, and description before the real page content. Even when Firecrawl's
// excludeTags removes the widget by selector, some sites use non-standard markup
// that slips through — this is a content-pattern-based backstop that catches
// the widget regardless of which consent platform generated it.
// We only strip when the "Cookie preferences...Reject All...Accept All" shape is
// present, so we never touch a page that legitimately mentions cookies once or twice.
function stripCookieBanner(md) {
  const bannerPattern = /Cookie preferences[\s\S]*?Reject All[\s\S]*?Accept All(?:\n\nPowered by[\s\S]*?\))?/i;
  return md.replace(bannerPattern, '');
}

// Strip image links and excess noise from markdown
const cleaned = pages.map(md =>
  stripCookieBanner(md)
    .replace(/!\[.*?\]\(.*?\)/g, '')      // remove image links
    .replace(/\n{3,}/g, '\n\n')           // collapse excess blank lines
    .trim()
);

const combinedContent = cleaned.join('\n\n---\n\n');

// Lead fields are pulled explicitly from the trigger — upstream nodes strip them
const trigger = $('Agent 1 Execution Trigger').item.json;

return {
  content: combinedContent,
  pages_scraped: pages.length,
  pages_attempted: items.length,
  lead_id: trigger.lead_id,
  website: trigger.website,
  company_name: trigger.company_name,
  email: trigger.email,
  chat_id: trigger.chat_id,
  place_id: trigger.place_id
};

const response = $input.first().json;
const analysisData = response.output?.[0]?.content?.[0]?.text;
const leadData = $('Prepare Pages for Analysis').first().json;

return {
  lead_id: leadData.lead_id,
  website: leadData.website,
  company_name: leadData.company_name,
  email: leadData.email,
  chat_id: leadData.chat_id,
  scraped_content: leadData.content,
  pain_points: analysisData?.pain_points || [],
  automation_gaps: analysisData?.automation_gaps || [],
  confidence: analysisData?.confidence || 'low',
  notes: analysisData?.notes || ''
};

const xml = $json.data || '';

const keywords = [
  'about', 'contact', 'team', 'staff', 'menu', 'services', 'service',
  'branch', 'branches', 'location', 'feedback', 'review', 'testimonial',
  'sell', 'let', 'rent', 'property', 'valuation', 'price', 'pricing'
];

// Extract all <loc> entries from the sitemap
const locMatches = [...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map(m => m[1]);

// Score relevance by counting matched keywords in the URL path
const scored = locMatches
  .map(url => {
    const lower = url.toLowerCase();
    const matchCount = keywords.filter(kw => lower.includes(kw)).length;
    return { url, matchCount };
  })
  .filter(item => item.matchCount > 0)
  .sort((a, b) => b.matchCount - a.matchCount);

const relevantUrls = scored.slice(0, 10).map(item => item.url);

// Lead fields are pulled explicitly from the trigger — HTTP Request/IF nodes strip them
const trigger = $('Agent 1 Execution Trigger').item.json;

return {
  relevant_urls: relevantUrls,
  total_sitemap_urls: locMatches.length,
  lead_id: trigger.lead_id,
  website: trigger.website,
  company_name: trigger.company_name,
  email: trigger.email,
  chat_id: trigger.chat_id,
  place_id: trigger.place_id
};

const place = $json;

// Take up to 5 most recent reviews and format them as rating + text for GPT
const reviews = (place.reviews || []).slice(0, 5).map(r => {
  const text = r.text?.text || '(no text)';
  const rating = r.rating ?? 'unknown';
  const when = r.relativePublishTimeDescription || '';
  return `Rating: ${rating}/5 (${when})\n${text}`;
});

const reviewsBlock = reviews.length > 0
  ? reviews.join('\n\n---\n\n')
  : 'No reviews available.';

// Lead fields are pulled explicitly from the trigger — upstream nodes strip them
const trigger = $('Agent 1 Execution Trigger').item.json;

return {
  google_rating: place.rating ?? null,
  review_count: place.userRatingCount ?? 0,
  reviews_block: reviewsBlock,
  lead_id: trigger.lead_id,
  website: trigger.website,
  company_name: trigger.company_name,
  email: trigger.email,
  chat_id: trigger.chat_id,
  place_id: trigger.place_id
};

function safeGetNode(nodeName) {
  try {
    return $(nodeName).first().json;
  } catch (e) {
    return null;
  }
}

const trigger = $('Agent 1 Execution Trigger').item.json;
const companyName = trigger.company_name || '';

const GENERIC_WORDS = ['restaurant', 'the', 'and', 'cafe', 'bar', 'amsterdam', 'grill', 'bistro'];
const nameTokens = companyName
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, '')
  .split(/\s+/)
  .filter(t => t.length >= 3 && !GENERIC_WORDS.includes(t));

const IG_PROFILE = /^https?:\/\/(?:www\.)?instagram\.com\/([a-zA-Z0-9_.]+)\/?(?:\?.*)?$/i;
const FB_PROFILE = /^https?:\/\/(?:www\.)?facebook\.com\/([a-zA-Z0-9_.\-]+)\/?(?:\?.*)?$/i;
const FB_EXCLUDED_SLUGS = ['login', 'help', 'policies', 'marketplace', 'groups', 'watch', 'sharer', 'pages', 'public'];

// For single-word/dictionary names (risk of collision, like "Roux" → singer
// La Roux), a positive whitelist of culinary words catches too few —
// ordinary business posts (closing for renovations, announcements) often lack any
// "food" vocabulary. A denylist is more reliable: block obvious signs of show business/
// non-restaurant-related content, rather than requiring proof that "it's a restaurant."
const NON_BUSINESS_RED_FLAGS = [
  'singer', 'musician', 'artist', 'band', ' tour', 'presale', 'pre-sale',
  'ticket', 'album', 'fan club', ' dj ', 'actress', 'actor', 'footballer',
  'athlete', 'official artist'
];

function findProfile(searchResult, profileRegex, excludedSlugs = []) {
  const items = searchResult?.organic || [];
  for (const item of items.slice(0, 5)) {
    const link = item.link || '';
    const match = link.match(profileRegex);
    if (!match) continue;

    const slug = match[1].toLowerCase();
    if (excludedSlugs.includes(slug)) continue;

    const title = (item.title || '').toLowerCase();
    const snippet = (item.snippet || '').toLowerCase();
    const text = title + ' ' + snippet;

    const hasNameMatch = nameTokens.length === 0 || nameTokens.some(t => title.includes(t) || slug.includes(t));
    if (!hasNameMatch) continue;

    if (nameTokens.length === 1) {
      const hasRedFlag = NON_BUSINESS_RED_FLAGS.some(w => text.includes(w));
      if (hasRedFlag) continue;
    }

    return { found: true, url: item.link, title: item.title, snippet: item.snippet };
  }
  return { found: false, url: null, title: null, snippet: null };
}

const igResult = safeGetNode('Serper Instagram Search');
const fbResult = safeGetNode('Serper Facebook Search');

const instagram = findProfile(igResult, IG_PROFILE);
const facebook = findProfile(fbResult, FB_PROFILE, FB_EXCLUDED_SLUGS);

return {
  lead_id: trigger.lead_id,
  website: trigger.website,
  company_name: trigger.company_name,
  email: trigger.email,
  chat_id: trigger.chat_id,
  place_id: trigger.place_id,
  instagram,
  facebook
};

const response = $input.first().json;
const raw = response.output?.[0]?.content?.[0]?.text;

let data;
if (typeof raw === 'object' && raw !== null) {
  data = raw;
} else if (typeof raw === 'string') {
  try {
    data = JSON.parse(raw.replace(/```json|```/g, '').trim());
  } catch (e) {
    data = {};
  }
} else {
  data = {};
}

// Lead fields are pulled explicitly from the trigger — upstream nodes strip them
const trigger = $('Agent 1 Execution Trigger').item.json;

return {
  lead_id: trigger.lead_id,
  website: trigger.website,
  company_name: trigger.company_name,
  email: trigger.email,
  chat_id: trigger.chat_id,
  place_id: trigger.place_id,
  google_rating: $('Prepare Place Reviews').first().json.google_rating,
  review_count: $('Prepare Place Reviews').first().json.review_count,
  recurring_praise: data.recurring_praise || [],
  recurring_complaints: data.recurring_complaints || [],
  automation_signals: data.automation_signals || [],
  review_confidence: data.confidence || 'low',
  review_notes: data.notes || ''
};

// Formats a single item regardless of whether GPT returned a plain string
// or a structured object (different prompts use different key names)
function formatItem(item) {
  if (typeof item === 'string') return item;
  if (item && typeof item === 'object') {
    const main = item.point || item.opportunity || item.theme || item.pattern || Object.values(item)[0];
    const evidence = item.evidence;
    if (main && evidence && main !== evidence) {
      return `${main} (Evidence: ${evidence})`;
    }
    return main ? String(main) : Object.entries(item).map(([k, v]) => `${k}: ${v}`).join(' | ');
  }
  return String(item);
}

// Helper: join an array of strings/objects into readable bullet text, or return a fallback if empty
function joinList(arr, fallback) {
  if (!Array.isArray(arr) || arr.length === 0) return fallback;
  return arr.map(item => `- ${formatItem(item)}`).join('\n');
}

const data = $input.first().json;

// pain_points: combine site-derived pain points with recurring complaints from reviews
const painPointsParts = [];
if (Array.isArray(data.pain_points) && data.pain_points.length > 0) {
  painPointsParts.push('[Site]\n' + joinList(data.pain_points, ''));
}
if (Array.isArray(data.recurring_complaints) && data.recurring_complaints.length > 0) {
  painPointsParts.push('[Reviews]\n' + joinList(data.recurring_complaints, ''));
}
const pain_points = painPointsParts.length > 0
  ? painPointsParts.join('\n\n')
  : 'No clear pain points identified from available data.';

// automation_gaps: combine site-derived gaps with automation signals from reviews
const automationParts = [];
if (Array.isArray(data.automation_gaps) && data.automation_gaps.length > 0) {
  automationParts.push('[Site]\n' + joinList(data.automation_gaps, ''));
}
if (Array.isArray(data.automation_signals) && data.automation_signals.length > 0) {
  automationParts.push('[Reviews]\n' + joinList(data.automation_signals, ''));
}
const automation_gaps = automationParts.length > 0
  ? automationParts.join('\n\n')
  : 'No clear automation gaps identified from available data.';

// review_patterns: recurring praise + complaints as a standalone readable block
const reviewPatternsParts = [];
if (Array.isArray(data.recurring_praise) && data.recurring_praise.length > 0) {
  reviewPatternsParts.push('Praise:\n' + joinList(data.recurring_praise, ''));
}
if (Array.isArray(data.recurring_complaints) && data.recurring_complaints.length > 0) {
  reviewPatternsParts.push('Complaints:\n' + joinList(data.recurring_complaints, ''));
}
const review_patterns = reviewPatternsParts.length > 0
  ? reviewPatternsParts.join('\n\n')
  : 'No clear review patterns identified.';

// social_signals: human-readable summary of Instagram/Facebook findings
function formatSocial(name, obj) {
  if (obj?.found) {
    return `${name}: FOUND\nURL: ${obj.url}\nTitle: ${obj.title}\nSnippet: ${obj.snippet}`;
  }
  return `${name}: not found`;
}
const social_signals = [
  formatSocial('Instagram', data.instagram),
  formatSocial('Facebook', data.facebook)
].join('\n\n');

// analysis_notes: combine caveats from both GPT analyses
const notesParts = [];
if (data.notes) notesParts.push('[Site] ' + data.notes);
if (data.review_notes) notesParts.push('[Reviews] ' + data.review_notes);
const analysis_notes = notesParts.length > 0 ? notesParts.join('\n') : '';

return {
  lead_id: data.lead_id,
  website: data.website,
  company_name: data.company_name,
  email: data.email,
  chat_id: data.chat_id,
  place_id: data.place_id,
  content: data.scraped_content || '',
  pain_points,
  automation_gaps,
  google_rating: data.google_rating ?? null,
  review_count: data.review_count ?? 0,
  review_patterns,
  social_signals,
  site_confidence: data.confidence || 'low',
  review_confidence: data.review_confidence || 'low',
  analysis_notes
};
